package nl.smartstreamlabs.sbwdroneconfig;
import net.minecraft.world.*;import net.minecraft.world.inventory.*;import net.minecraft.world.entity.player.*;import net.minecraft.world.item.ItemStack;import net.minecraft.network.FriendlyByteBuf;
public class Ndc01Menu extends AbstractContainerMenu implements PlatformInventoryState {
 private final ContainerData inventoryState;public ContainerData inventoryState(){return inventoryState;}
 public final int carrierId;private final Ndc01Entity carrier;private final ContainerData data;
 public Ndc01Menu(int id,Inventory inv,FriendlyByteBuf buf){this(id,inv,buf.readInt(),null);}
 public Ndc01Menu(int id,Inventory inv,Ndc01Entity c){this(id,inv,c.getId(),c);}
 private Ndc01Menu(int id,Inventory inv,int entity,Ndc01Entity c){super(AddonMenus.NDC01.get(),id);carrierId=entity;carrier=c;Container items=c==null?new SimpleContainer(18):c.bays;for(int i=0;i<18;i++){final int slot=i;addSlot(new Slot(items,i,17+(i%3)*44,34+(i/3)*20){public int getMaxStackSize(){return 1;}public boolean mayPlace(ItemStack s){return Ndc01Entity.allowed(s)&&(carrier==null||!carrier.busy()&&!PlatformInventory.editing(carrier));}public boolean mayPickup(Player p){return carrier==null||!carrier.busy()&&!PlatformInventory.editing(carrier);}});}for(int row=0;row<3;row++)for(int col=0;col<9;col++)addSlot(new Slot(inv,col+row*9+9,151+col*18,169+row*18));for(int col=0;col<9;col++)addSlot(new Slot(inv,col,151+col*18,227));
  data=c==null?new SimpleContainerData(24):new ContainerData(){public int get(int i){if(i<18)return c.state(i);if(i==18)return c.bay();if(i==19)return c.reason();if(i==20)return c.getEnergy()&65535;if(i==21)return c.getEnergy()>>>16;if(i==22)return c.getMaxEnergy()/1000;if(i==23){var t=c.selectedTarget==null?null:c.defenseLevel().getEntity(c.selectedTarget);return t==null?-1:t.getId();}return 0;}public void set(int i,int v){}public int getCount(){return 24;}};addDataSlots(data);inventoryState=PlatformInventory.status(carrier,()->carrier==null?-1:carrier.bay());addDataSlots(inventoryState);
 }
 public int state(int slot){return data.get(slot);}public int selected(){return data.get(18);}public int reason(){return data.get(19);}public int energy(){return(data.get(20)&65535)|((data.get(21)&65535)<<16);}public int capacity(){return data.get(22)*1000;}public int target(){return data.get(23);}
 @Override public boolean stillValid(Player p){var e=p.level().getEntity(carrierId);return e instanceof Ndc01Entity c&&c.isAlive()&&!c.isRemoved()&&!c.isWreck()&&(p.level().isClientSide||p instanceof net.minecraft.server.level.ServerPlayer sp&&c.canUse(sp));}
 @Override public boolean clickMenuButton(Player p,int action){if(carrier==null||!stillValid(p)||!(p instanceof net.minecraft.server.level.ServerPlayer sp))return false;carrier.action(sp,action);return true;}
 @Override public ItemStack quickMoveStack(Player p,int slot){if(slot<0||slot>=slots.size()||carrier!=null&&(carrier.busy()||PlatformInventory.editing(carrier)))return ItemStack.EMPTY;var s=slots.get(slot);if(!s.hasItem())return ItemStack.EMPTY;var stack=s.getItem();var copy=stack.copy();if(slot<18){if(!moveItemStackTo(stack,18,54,true))return ItemStack.EMPTY;}else{if(!Ndc01Entity.allowed(stack)||!moveItemStackTo(stack,0,18,false))return ItemStack.EMPTY;}if(stack.isEmpty())s.setByPlayer(ItemStack.EMPTY);else s.setChanged();return copy;}
}
